INSERT INTO `ai_briefs` VALUES (1,'abf52ae487b37967f71e60ab4da414db7a398414953c1e1880eb257e677d13a6','OpenAI News','Making ChatGPT better for clinicians',NULL,'OpenAI makes ChatGPT for Clinicians free for verified U.S. physicians, nurse practitioners, and pharmacists, supporting clinical care, documentation, and research.',NULL,'pending',NULL,'https://openai.com/index/making-chatgpt-better-for-clinicians','2026-04-22 15:00:00.000','2026-04-23 09:05:07.543','2026-04-23 09:05:07.543'),(2,'6bc4afedb226072f4f19ef0e1e675bb8e4143f02ee108c7e905c28d98a88769d','OpenAI News','Workspace agents',NULL,'Learn how to build, use, and scale workspace agents in ChatGPT to automate repeatable workflows, connect tools, and streamline team operations.',NULL,'pending',NULL,'https://openai.com/academy/workspace-agents','2026-04-22 10:00:00.000','2026-04-23 09:05:07.543','2026-04-23 09:05:07.543'),(3,'dca5643d9bc6c40c6b267e66d78778614dfc697da802cf3357063edcf3b8e9d8','OpenAI News','Introducing workspace agents in ChatGPT',NULL,'Workspace agents in ChatGPT are Codex-powered agents that automate complex workflows, run in the cloud, and help teams scale work across tools securely.',NULL,'pending',NULL,'https://openai.com/index/introducing-workspace-agents-in-chatgpt','2026-04-22 10:00:00.000','2026-04-23 09:05:07.543','2026-04-23 09:05:07.543'),(4,'4342a09f59450652a7d8f64e8caefe325c676e452bedcb0ab994e0b2d39da477','OpenAI News','Speeding up agentic workflows with WebSockets in the Responses API',NULL,'A deep dive into the Codex agent loop, showing how WebSockets and connection-scoped caching reduced API overhead and improved model latency.',NULL,'pending',NULL,'https://openai.com/index/speeding-up-agentic-workflows-with-websockets','2026-04-22 10:00:00.000','2026-04-23 09:05:07.543','2026-04-23 09:05:07.543'),(5,'1ecb89da4889ca3e30cee4acbd6943ef8c515da5aa54d37f755e6db0d875b995','OpenAI News','Introducing OpenAI Privacy Filter',NULL,'OpenAI Privacy Filter is an open-weight model for detecting an