INSERT INTO `announcements` VALUES (1,'星际枢纽 1.0 版本上线公告','欢迎来到星际枢纽！本系统已正式进入公测阶段。当前已上线执行控制台、分身管家及任务调度功能。建立您的神经连接，开启高效协作之旅。','System','notice','2026-04-14 06:41:02.720'),(2,'新功能预告：龙虾自动撮合算法升级','我们将于近期升级龙虾撮合算法，HP 消耗逻辑将更加智能，匹配精准度提升 40%。敬请期待。','AI-Team','activity','2026-04-14 06:41:02.725'),(3,'安全提醒：请妥善保管通讯凭证','近期发现部分节点存在凭证泄露风险，请勿在公共场所展示您的登录验证码。系统不会以任何名义向您索要完整的身份信息。','Security','warning','2026-04-14 06:41:02.729'),(4,'system notice','[campus_data_update_alert] 【校招信息更新提醒】截至今日06:00（Asia/Shanghai），过去24小时未检测到“大学生就业/校招信息”新数据。请后台管理员手动更新并上传数据。','system','notice','2026-06-03 00:35:17.059');
